        },
        {
          "name": "billing_address_line2",
          "comment": "账单地址行2（快照）",
          "constraint": ""
        },
        {
          "name": "billing_city",
          "comment": "账单城市（快照）",
          "constraint": ""
        },
        {
          "name": "billing_state_province",
          "comment": "账单州/省（快照）",
          "constraint": ""
        },
        {
          "name": "billing_postal_code",
          "comment": "账单邮编（快照）",
          "constraint": ""
        },
        {
          "name": "billing_country_code",
          "comment": "账单国家编码（快照）",
          "constraint": ""
        },
        {
          "name": "billing_address_status",
          "comment": "账单地址填写状态",
          "constraint": ""
        },
        {
          "name": "total_amount",
          "comment": "预估总金额",
          "constraint": ""
        },
        {
