    },
    {
      "name": "checkout_session_item",
      "comment": "结算会话商品",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "session_id",
          "comment": "所属会话（→ checkout_session）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "渠道上架（→ listing）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "unit_price",
          "comment": "单价（快照）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        }
      ],
      "note": "快照结算时的商品和价格，用于弃单恢复"
    },
    {
      "name": "checkout_discount_attempt",
