        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "session_id",
          "comment": "所属会话（→ checkout_session）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "discount_code",
          "comment": "优惠码码值（统一大写存储）",
          "constraint": ""
        },
        {
          "name": "code_source",
          "comment": "码来源（链接带入 / 买家手输）",
          "constraint": ""
        },
        {
          "name": "attempt_result",
          "comment": "校验结果（已应用 / 未通过）",
          "constraint": ""
        },
        {
          "name": "reject_reason",
          "comment": "未通过原因（营销校验链九类 + 其他）",
          "constraint": ""
        },
        {
          "name": "discount_amount",
          "comment": "本次减免金额（未通过为 0）",
          "constraint": ""
