          "comment": "支付单号（→ 支付模块）",
          "constraint": ""
        },
        {
          "name": "payment_deadline",
          "comment": "待付款超时时间（下单+1自然日）",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "付款到账时间",
          "constraint": ""
        },
        {
          "name": "cancelled_at",
          "comment": "取消时间（待付款取消）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
