          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_status",
          "comment": "订单状态",
          "constraint": ""
        },
        {
          "name": "subtotal_amount",
          "comment": "商品小计",
          "constraint": ""
        },
        {
          "name": "discount_amount",
          "comment": "优惠总金额（冗余汇总）",
          "constraint": ""
        },
        {
          "name": "shipping_fee",
          "comment": "运费",
          "constraint": ""
        },
        {
          "name": "tax_amount",
          "comment": "税费（按收货州税率）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "address_id",
          "comment": "收货地址ID（→ address.id UUID）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "recipient_first_name",
          "comment": "收件人名（快照）",
          "constraint": ""
        },
        {
          "name": "recipient_last_name",
          "comment": "收件人姓（快照）",
          "constraint": ""
        },
        {
          "name": "recipient_name",
          "comment": "收件人全名（快照，冗余拼接）",
          "constraint": ""
        },
        {
          "name": "recipient_phone",
          "comment": "收件人电话（快照，含区号）",
          "constraint": ""
        },
        {
          "name": "shipping_address_line1",
          "comment": "地址行1（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_address_line2",
          "comment": "地址行2（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_city",
          "comment": "城市（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_state_province",
          "comment": "州/省（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_postal_code",
          "comment": "邮编（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_country_code",
          "comment": "国家编码（快照）",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "付款到账时间（继承父订单）",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "交易完成时间",
          "constraint": ""
