          "constraint": ""
        },
        {
          "name": "condition_grade",
          "comment": "成色等级（快照）",
          "constraint": ""
        },
        {
          "name": "quantity",
          "comment": "数量（二手默认1）",
          "constraint": ""
        },
        {
          "name": "unit_price",
          "comment": "成交单价（快照）",
