        },
        {
          "name": "discount_amount",
          "comment": "优惠分摊合计（冗余汇总）",
          "constraint": ""
        },
        {
          "name": "item_total",
          "comment": "实付小计（单价×数量-优惠）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "fulfillment_status",
          "comment": "发货状态",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款状态",
          "constraint": ""
