        },
        {
          "name": "package_status",
          "comment": "包裹状态",
          "constraint": ""
        },
        {
          "name": "shipped_at",
          "comment": "发货时间",
          "constraint": ""
        },
        {
          "name": "received_at",
          "comment": "签收时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "物理包裹，通常1订单=1包裹，装不下时拆多包裹"
    },
    {
      "name": "refund_request",
      "comment": "退款申请单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
