        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "refund_type",
          "comment": "退款类型",
          "constraint": ""
        },
        {
          "name": "refund_reason",
          "comment": "退款原因",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "申请退款金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "approval_status",
          "comment": "审批状态",
          "constraint": ""
        },
        {
          "name": "request_channel",
          "comment": "申请渠道",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "处理人ID",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "处理人类型",
          "constraint": ""
        },
        {
          "name": "operator_note",
          "comment": "处理备注",
          "constraint": ""
        },
        {
          "name": "refund_ref_no",
          "comment": "退款单号（→ refund_order，审批通过后写入）",
          "constraint": ""
        },
        {
          "name": "requested_at",
          "comment": "申请时间",
          "constraint": ""
        },
        {
          "name": "approved_at",
          "comment": "审批通过时间",
          "constraint": ""
        },
        {
          "name": "rejected_at",
          "comment": "驳回时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "业务域：管审批决策，不管资金操作。审批通过后由支付域创建 refund_order"
